contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address vault, address asset, uint256 slope0) public {
        require(slope0 > 0);
        // NOTE: setLimits and setSlopes are access-controlled and C was initialized by the test
        // via initialize(address) elsewhere; in this harness we assume the test contract is
        // already authorized. If not, the calls below would revert and the rule would be vacuous.
        c.setLimits(type(uint256).max, 0, 0);
        c.setSlopes(asset, IVaultAdapter.SlopeData({kink: 1e27, slope0: slope0, slope1: 0}));

        uint256 beforeRate = c.rate(vault, asset);
        uint256 afterRate = c.rate(vault, asset);

        assert(beforeRate == slope0 && afterRate == slope0);
    }

    receive() external payable {}
}

