contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address accessControl,
        bytes4 selector,
        address asset,
        uint256 kink,
        uint256 slope0,
        uint256 slope1,
        bool revokeSelf
    ) public {
        // Initialize c (fresh deployment, so this should succeed).
        c.initialize(accessControl);

        // Build the access control setup: grant access to the test contract, or if the caller is the
        // access-control contract itself, it may already have access through its own logic.
        // We cannot directly call grantAccess on the access control because it is an external contract
        // not declared here. Instead, we rely on the fact that this test contract deployed c and is
        // the caller for every call.
        //
        // For the property we want to explore both revert and success cases. We can control access
        // by making the accessControl address be the test contract itself, but we cannot implement
        // checkAccess here (only one public function allowed). So we assume the provided accessControl
        // is an already-deployed access control that grants the test contract access for all selectors
        // by default, or we can attempt to call setSlopes and observe.
        //
        // Since we cannot set up access control generically, we simply call setSlopes and check that:
        // - If kink == 0 or kink >= 1e27, it always reverts (regardless of access).
        // - If kink is valid (0 < kink < 1e27), it either reverts due to access control or succeeds.
        // The general rule we assert is about the validity condition.

        IVaultAdapter.SlopeData memory slopes = IVaultAdapter.SlopeData({
            kink: kink,
            slope0: slope0,
            slope1: slope1
        });

        bool reverted;
        try c.setSlopes(asset, slopes) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: setSlopes must revert if the kink is zero or at least 1e27.
        // If the kink is valid, it may still revert due to access control, but if it does not revert,
        // the call must have succeeded (state change). We cannot directly read private state, but we
        // can check that the revert flag is consistent with the kink validity.
        // We also check a weaker condition: if kink is valid, reverted is either true (access) or false
        // (success). Since we cannot distinguish, we assert the stronger condition on invalid kinks.
        // Additionally, we assert that for a valid kink, the call is not guaranteed to revert; however
        // we cannot force success without access control setup. So the rule: invalid kink always reverts.
        // This is a general rule that holds for all inputs because the contract checks kink before
        // access control? Actually in the code, checkAccess modifier runs first, so if access is denied,
        // it reverts even for valid kinks. However, for invalid kinks, it still reverts, but the reason
        // could be access denied. The property "if kink invalid then revert" holds regardless.
        // But we need a condition that is true for all inputs. If access is denied for all calls,
        // then any kink reverts, so the implication "invalid kink => revert" is true, but "valid kink =>
        // not revert" is false. The rule we can safely assert is: if the call did NOT revert, then the
        // kink must be valid (because invalid kink would have reverted). That is a general rule.
        // So: assert(revokeSelf || !reverted || (kink > 0 && kink < 1e27));
        // But revokeSelf is unused; remove it.

        assert(!reverted || (kink > 0 && kink < 1e27));
    }
}

